阅读下面程序，输出结果是：
#include <iostream>
using namespace std;
class A {
public:
    virtual void Func(){cout <<"A::Func"<<endl;}
};
class B:public A {
public:
    virtual void Func(){cout <<"B::Func"<<endl;}
};
int main(){
    A a;
    A *pa = new B();
    pa->Func();
    long *p1 = (long *)&a;
    long *p2 = (long *)pa;
    *p2 = *p1;
    pa->Func();
    return 0;
}
